INSERT INTO public.support_quick_replies VALUES ('00000000-0000-4000-8000-000000000238', 'Looking into it', 'Hello {name}, thank you for telling us. We are looking into it now and will get back to you shortly.', NULL, '2026-01-01 00:00:00+00');
INSERT INTO public.support_quick_replies VALUES ('00000000-0000-4000-8000-000000000239', 'Try clock-in again', 'Hello {name}, please close Xtend completely, make sure Location, Camera and Notifications are allowed, stand outside in the open for a minute, then try to clock in again. Tell us here if it still does not work.', NULL, '2026-01-01 00:00:00+00');
INSERT INTO public.support_quick_replies VALUES ('00000000-0000-4000-8000-000000000240', 'Fixed, try again', 'Hello {name}, this has been fixed on our side. Please try again now and let us know if anything is still wrong.', NULL, '2026-01-01 00:00:00+00');
INSERT INTO public.support_quick_replies VALUES ('00000000-0000-4000-8000-000000000241', 'Store change done', 'Hello {name}, your store has been updated. Close and open Xtend again to see it.', NULL, '2026-01-01 00:00:00+00');
INSERT INTO public.support_quick_replies VALUES ('00000000-0000-4000-8000-000000000242', 'Call your supervisor', 'Hello {name}, please call your supervisor about this today so they can sort it out with you directly.', NULL, '2026-01-01 00:00:00+00');
